    private static void eq(long[] expected, long[] actual) {
        checks++;
        if (!Arrays.equals(expected, actual))
            throw new AssertionError(Arrays.toString(expected) + " != " + Arrays.toString(actual));
    }

    private static void fails(Class<? extends Throwable> expected, Runnable task) {
        checks++;
        try { task.run(); }
        catch (Throwable found) {
            if (expected.isInstance(found)) return;
            throw new AssertionError("unexpected exception " + found, found);
        }
        throw new AssertionError("expected " + expected.getName());
    }
